(function ($) {
    $(function () {
        $("#date_hierarchy-form").submit(function (event) {
            let dtInicial = $("#input-date_hierarchy-init");
            let dtFinal = $("#input-date_hierarchy-end");
            dtInicial.val(dtInicial.val().replace(/(\d{2})\/(\d{2})\/(\d{4})/, '$3-$2-$1'));
            dtFinal.val(dtFinal.val().replace(/(\d{2})\/(\d{2})\/(\d{4})/, '$3-$2-$1'));
        })
    });
})(django.jQuery);